using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Threading.RateLimiting;

namespace ResearchTrack.Gateway;

/// <summary>
/// Explicitly approved load-generation source. A public IP alone is not an
/// authentication factor: both the true forwarded client IP and a secret header
/// must match. Only the general API bucket can be exempted.
/// </summary>
public sealed class PerformanceRateLimitPolicy
{
    public const string AuthorizationHeader = "X-ResearchTrack-Performance-Key";

    private readonly IPAddress? _allowedIp;
    private readonly byte[]? _tokenBytes;

    public bool Enabled { get; }

    public PerformanceRateLimitPolicy(IConfiguration configuration)
    {
        Enabled = configuration.GetValue<bool>("RateLimiting:PerformanceTest:Enabled");
        if (!Enabled)
        {
            return;
        }

        var ip = configuration["RateLimiting:PerformanceTest:AllowedIp"];
        var token = configuration["RateLimiting:PerformanceTest:Token"];
        if (!IPAddress.TryParse(ip, out var allowedIp) ||
            IPAddress.Any.Equals(allowedIp) || IPAddress.IPv6Any.Equals(allowedIp) ||
            IPAddress.IsLoopback(allowedIp))
        {
            throw new InvalidOperationException(
                "RateLimiting:PerformanceTest:AllowedIp must be one explicit, non-loopback IP address.");
        }

        if (string.IsNullOrWhiteSpace(token) || token.Length < 32 ||
            token.Contains("CHANGE_ME", StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException(
                "RateLimiting:PerformanceTest:Token must be a non-placeholder secret of at least 32 characters.");
        }

        _allowedIp = Normalize(allowedIp);
        _tokenBytes = Encoding.UTF8.GetBytes(token);
    }

    public bool IsExempt(HttpContext context)
    {
        if (!Enabled || _allowedIp is null || _tokenBytes is null ||
            context.Connection.RemoteIpAddress is not { } remote ||
            !Normalize(remote).Equals(_allowedIp))
        {
            return false;
        }

        var provided = context.Request.Headers[AuthorizationHeader];
        if (provided.Count != 1 || string.IsNullOrEmpty(provided[0]))
        {
            return false;
        }

        var suppliedBytes = Encoding.UTF8.GetBytes(provided[0]!);
        return CryptographicOperations.FixedTimeEquals(suppliedBytes, _tokenBytes);
    }

    public (string Bucket, int PermitLimit) SelectBucket(string path) => path switch
    {
        "/api/v1/auth/login" => ("auth-login", 10),
        "/api/v1/auth/refresh" => ("auth-refresh", 30),
        "/api/v1/auth/forgot-password" => ("auth-forgot-password", 5),
        "/api/v1/auth/reset-password" => ("auth-reset-password", 10),
        "/api/github/webhooks" or "/api/v1/github/webhooks" => ("github-webhooks", 600),
        _ => ("general", 120)
    };

    public RateLimitPartition<string> Partition(HttpContext context)
    {
        var remoteIp = context.Connection.RemoteIpAddress?.ToString() ?? "unknown";
        var (bucket, permits) = SelectBucket(context.Request.Path.Value ?? string.Empty);
        if (bucket == "general" && IsExempt(context))
        {
            // The specially authorized VPS measures backend capacity without
            // the normal per-IP general bucket masking the result with 429s.
            return RateLimitPartition.GetNoLimiter($"performance:{remoteIp}");
        }

        return RateLimitPartition.GetFixedWindowLimiter(
            $"{bucket}:{remoteIp}",
            _ => new FixedWindowRateLimiterOptions
            {
                PermitLimit = permits,
                Window = TimeSpan.FromMinutes(1),
                QueueLimit = 0,
                AutoReplenishment = true
            });
    }

    private static IPAddress Normalize(IPAddress address) =>
        address.IsIPv4MappedToIPv6 ? address.MapToIPv4() : address;
}

using Prometheus;
using ResearchTrack.BuildingBlocks.Api.Constants;
using ResearchTrack.BuildingBlocks.Api.Extensions;
using ResearchTrack.BuildingBlocks.Api.Infrastructure;
using ResearchTrack.Gateway;

var builder = WebApplication.CreateBuilder(args);
builder.WebHost.ConfigureKestrel(options =>
{
    options.AddServerHeader = false;

    var urls = Environment.GetEnvironmentVariable("ASPNETCORE_URLS");
    if (!string.IsNullOrWhiteSpace(urls))
    {
        foreach (var url in urls.Split(';', StringSplitOptions.RemoveEmptyEntries))
        {
            var uri = new Uri(url.Replace("+", "0.0.0.0").Replace("*", "0.0.0.0"));
            options.Listen(System.Net.IPAddress.Any, uri.Port);
        }
    }
    else
    {
        options.ListenAnyIP(5000); // local fallback, matches launchSettings default
    }

    options.ListenAnyIP(9100); // internal-only metrics port, never published to host or edge
});

// Keep config/env/gateway/.env.example as the single gateway configuration contract.
// Local scripts already map these friendly variables to ASP.NET configuration keys;
// container deployments inject the same variables directly, so map them here as well.
var gatewayEnvironmentOverrides = new Dictionary<string, string?>
{
    ["Frontend:AllowedOrigins:0"] = Environment.GetEnvironmentVariable("FRONTEND_ORIGIN"),
    ["ReverseProxy:Clusters:auth:Destinations:primary:Address"] = Environment.GetEnvironmentVariable("AUTH_SERVICE_URL"),
    ["ReverseProxy:Clusters:project:Destinations:primary:Address"] = Environment.GetEnvironmentVariable("PROJECT_SERVICE_URL"),
    ["ReverseProxy:Clusters:github:Destinations:primary:Address"] = Environment.GetEnvironmentVariable("GITHUB_SERVICE_URL"),
    ["ReverseProxy:Clusters:jira:Destinations:primary:Address"] = Environment.GetEnvironmentVariable("JIRA_SERVICE_URL"),
    ["ReverseProxy:Clusters:meeting:Destinations:primary:Address"] = Environment.GetEnvironmentVariable("MEETING_SERVICE_URL"),
    ["ReverseProxy:Clusters:submission:Destinations:primary:Address"] = Environment.GetEnvironmentVariable("SUBMISSION_SERVICE_URL")
};

builder.Configuration.AddInMemoryCollection(
    gatewayEnvironmentOverrides.Where(pair => !string.IsNullOrWhiteSpace(pair.Value)));

builder.Services.AddResearchTrackApi("ResearchTrack API Gateway");
builder.Services.AddTrustedProxyForwarding();
builder.Services.AddReverseProxy().LoadFromConfig(builder.Configuration.GetSection("ReverseProxy"));

var allowedOrigins = builder.Configuration.GetSection("Frontend:AllowedOrigins").Get<string[]>() ?? Array.Empty<string>();
if (allowedOrigins.Length == 0)
{
    throw new InvalidOperationException("At least one Frontend:AllowedOrigins entry is required for the gateway.");
}

builder.Services.AddCors(options =>
{
    options.AddPolicy("frontend", policy =>
    {
        policy.WithOrigins(allowedOrigins)
            .AllowAnyHeader()
            .AllowAnyMethod()
            .AllowCredentials();
    });
});

// Fail at startup if an explicitly enabled performance exemption is misconfigured.
// Source-IP validation uses only trusted forwarded headers configured below.
var performanceRateLimit = new PerformanceRateLimitPolicy(builder.Configuration);
builder.Services.AddRateLimiter(options =>
{
    options.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
    options.GlobalLimiter = System.Threading.RateLimiting.PartitionedRateLimiter
        .Create<HttpContext, string>(performanceRateLimit.Partition);
    options.OnRejected = async (context, _) =>
    {
        if (!context.HttpContext.Response.HasStarted)
        {
            await ApiErrorResponseWriter.WriteAsync(
                context.HttpContext,
                StatusCodes.Status429TooManyRequests,
                ErrorCodes.RateLimited,
                "Too many requests. Please try again later.");
        }
    };
});

var app = builder.Build();
// Must run first so rate limiting, logging and YARP see the real client address.
app.UseForwardedHeaders();
app.UseHttpMetrics();
app.UseResearchTrackApi();
app.UseCors("frontend");
app.UseRateLimiter();
// The gateway is the only component that needs this secret. Never forward it
// to downstream services, and do not echo it to request/response logs.
app.Use(async (context, next) =>
{
    context.Request.Headers.Remove(PerformanceRateLimitPolicy.AuthorizationHeader);
    await next(context);
});
app.MapReverseProxy();
app.MapMetrics().RequireHost("*:9100"); // only answers on 9100, not the public 8080
app.Run();

